<template>
	<view class="container">
		<u-loading-page :loading="true" v-if="load" fontSize="28rpx" />
		<block v-else>
		<view class="connect-info" v-if="isConnect">
			<view class="top" @click="send('left')">
				<image src="@/static/my/link-cg.png" mode="widthFix"></image>
				<text class="sb-title">{{ deviceName }}</text>
				<text class="wz-title">当前状态：</text>
				<text class="status-title">（连接成功）</text>
			</view>
			<view class="center">
				<view class="center-bg">
					<image src="@/static/my/sb-yuanhuan.png" mode="widthFix" class="bg-img"></image>
					<view class="sb-jt one" 
					@touchstart.prevent="touchstart(0)" 
					@touchmove="touchmove(0)"
					@touchend="touchend(0)">
						<image src="@/static/my/sb-arrow-bg.png" mode="widthFix" class="jt-bg-img"
							v-show="jt_index == 0"></image>
						<image :src="jt_index == 0 ? '/static/my/sb-arrow-black.png' : '/static/my/sb-arrow-grey.png'"
							mode="widthFix" class="jt-img"></image>
					</view>
					<view class="sb-jt two" 
					@touchstart.prevent="touchstart(1)"
					@touchmove="touchmove(1)"
					@touchend="touchend(1)">
						<image src="@/static/my/sb-arrow-bg.png" mode="widthFix" class="jt-bg-img"
							v-show="jt_index == 1"></image>
						<image :src="jt_index == 1 ? '/static/my/sb-arrow-black.png' : '/static/my/sb-arrow-grey.png'"
							mode="widthFix" class="jt-img"></image>
					</view>
					<view class="sb-jt three" 
					@touchstart.prevent="touchstart(2)"
					@touchmove="touchmove(2)"
					@touchend="touchend(2)">
						<image src="@/static/my/sb-arrow-bg.png" mode="widthFix" class="jt-bg-img"
							v-show="jt_index == 2"></image>
						<image :src="jt_index == 2 ? '/static/my/sb-arrow-black.png' : '/static/my/sb-arrow-grey.png'"
							mode="widthFix" class="jt-img"></image>
					</view>
					<view class="sb-jt four"
					@touchstart.prevent="touchstart(3)"
					@touchmove="touchmove(3)"
					@touchend="touchend(3)">
						<image src="@/static/my/sb-arrow-bg.png" mode="widthFix" class="jt-bg-img"
							v-show="jt_index == 3"></image>
						<image :src="jt_index == 3 ? '/static/my/sb-arrow-black.png' : '/static/my/sb-arrow-grey.png'"
							mode="widthFix" class="jt-img"></image>
					</view>
				</view>
			</view>
			<view class="bot" v-if="false">
				<view class="bot-item">
					<image src="@/static/my/sb-gl.png" mode="widthFix"></image>
					<text>设备管理</text>
				</view>
				<view class="bot-item">
					<image src="@/static/my/sb-add.png" mode="widthFix"></image>
					<text>添加设备</text>
				</view>
				<view class="bot-item">
					<image src="@/static/my/sb-info.png" mode="widthFix"></image>
					<text>设备信息</text>
				</view>
			</view>
		</view>
		<view class="list-info" v-else>
			<block v-if="false">
				<view class="form">
					<view class="form-row">
						<view class="row-center">
							<u-input border="none" placeholder="输入发送内容" placeholderClass="placeholder28"
								:placeholderStyle="placeholderStyle" type="text" fontSize="28rpx" clearable
								v-model="content" />
						</view>
					</view>
				</view>
				<view class="submit">
					<button type="default" class="submit-btn" @click="send" :disabled="content == ''">发送</button>
				</view>
			</block>
			<view class="items" v-if="lists.length>0">
				<view style="height: 20rpx;"></view>
				<view class="item" v-for="(item,index) in lists" :key="index" @click="connect(item)">
					<image src="@/static/lanya.png" class="item-img" mode="aspectFit" />
					<view class="right">
						<view class="right-tit">{{item.name}}</view>
						<view class="right-time">{{item.deviceId}}</view>
					</view>
				</view>
				<u-loadmore class="load-more" :status="hasMore?'loading':'nomore'" :nomoreText="noMore" />
			</view>
			<view class="submit" v-if="!isSearch">
				<button class="submit-btn" :disabled="!openBluetoothSuccess"
					@click="startBluetoothDevicesDiscovery">开始搜索</button>
			</view>
		</view>
		</block>
	</view>
</template>

<script>
	var _this;
	// ArrayBuffer转16进制字符串示例
	function ab2hex(buffer) {
		const hexArr = Array.prototype.map.call(
			new Uint8Array(buffer),
			function(bit) {
				return ('00' + bit.toString(16)).slice(-2)
			}
		)
		return hexArr.join('')
	}

	function stringToHex(str) {
		let hex = '';
		for (let i = 0; i < str.length; i++) {
			hex += str.charCodeAt(i).toString(16);
		}
		return hex;
	}
	function getByteLength(str) {
	        let total = 0;
	        for (let i = 0; i < str.length; i++) {
	            const charCode = str.charCodeAt(i); // 获取每个字符的Unicode值
	            if (charCode <= 256) {
	                total += 1; // ASCII字符只占1个字节
	            } else {
	                total += 3; // Unicode字符占3个字节（UTF-8编码）
	            }
	        }
	        return total;
	}
	export default {
		data() {
			return {
				jt_index: -1,
				name: 'mingao',
				content: '',
				openBluetoothSuccess: false,
				isSearch: false,
				placeholderStyle: "color:#959595;",
				serviceId: '',
				characteristicId: '',
				services: [],
				writes: [],
				notifys: [],
				timeOutEvent: 0,
				momentInterval:'',
				momentNum:0,
				sustainInterval:'',
				sustainNum:0,
				upliftInterval:'',
				upliftNum:0,
				deviceCoding:''
			}
		},
		onLoad(e) {
			_this = this;
		},
		onUnload() {
			_this.stopBluetoothDevicesDiscovery()
			if (_this.deviceId) {
				_this.add_user_sb()
			}
			if (_this.isConnect) {
				_this.$u.vuex('isConnect', false)
				uni.closeBLEConnection({
				  // 这里的 deviceId 需要已经通过 createBLEConnection 与对应设备建立链接
				  'deviceId':_this.deviceId,
				  success(res) {
				    console.log('断开蓝牙链接成功:',res)
				  },
				  fail(fail) {
				  	console.log('断开蓝牙链接失败: ', fail);
				  }
				})
			}
		},
		onReady() {
			_this.getBluetoothAdapterState()
			uni.onBluetoothDeviceFound(function(res) {
				let device = res.devices[0]
				if (device.name.toLowerCase().indexOf(_this.name) != -1) {
					console.log(device)
					if (device.advertisServiceUUIDs.length > 0) {
						console.log('包含uuid', device.advertisServiceUUIDs)
					}
					_this.lists.push(device)
					_this.hasMore = false
					_this.stopBluetoothDevicesDiscovery()
				}else{
					console.log('未知设备: ',device);
				}
			})
		},
		methods: {
			//触摸事件
			touchstart(index){
				let str = ''
				switch (index) {
					case 0:
						str = '02'
						break;
					case 1:
						str = '04'
						break;
					case 2:
						str = '01'
						break;
					default:
						str = '03'
						break;
				}
				_this.jt_index = index
				console.log('触摸事件',str);
				this.timeOutEvent = setTimeout(() => {
					this.sustain(str);//长按方法
				}, 500); //这里设置定时器，定义长按500毫秒触发长按事件
				_this.moment(str)
				return false;
			},
			//触摸移动事件
			touchmove(index){
				console.log('触摸移动事件');
				clearTimeout(this.timeOutEvent); //清除定时器
				this.timeOutEvent = 0;
			},
			//触摸结束事件
			touchend(index){
				let str = ''
				switch (index) {
					case 0:
						str = '02'
						break;
					case 1:
						str = '04'
						break;
					case 2:
						str = '01'
						break;
					default:
						str = '03'
						break;
				}
				clearTimeout(this.timeOutEvent); //清除定时器
				clearTimeout(this.sustainInterval); //清除定时器
				_this.jt_index = -1
				_this.uplift(str)
				console.log('触摸结束事件');
			},
			//长按事件
			longPress(str){
				console.log('触发长按事件');
				_this.sustain(str)
			},
			//解析设备编号
			parseDeviceCoding(){
				let arr = _this.deviceName.split('_')
				_this.deviceCoding = arr[2]
				console.log("deviceCoding:",_this.deviceCoding);
			},
			moment(str){
				clearInterval(_this.momentInterval)
				_this.momentInterval = setInterval(()=>{
					if (_this.momentNum>=5) {
						clearInterval(_this.momentInterval)
						_this.momentNum = 0
					}else{
						_this.send(str,'01','触摸事件')
						_this.momentNum++
					}
				},100)
			},
			sustain(str){
				clearInterval(_this.sustainInterval)
				_this.sustainInterval = setInterval(()=>{
					_this.send(str,'02','触发长按事件')
				},100)
			},
			uplift(str){
				clearInterval(_this.upliftInterval)
				_this.upliftInterval = setInterval(()=>{
					if (_this.upliftNum>=5) {
						clearInterval(_this.upliftInterval)
						_this.upliftNum = 0
					}else{
						_this.send(str,'03','触摸结束事件')
						_this.upliftNum++
					}
				},100)
			},
			/**
			 * 发送
			 * @param {Object} str1 按键编号(1:下键，2:上键，3:左键，4:右键)
			 * @param {Object} str2 按键状态
			 * 		01 按下瞬间状态重复发送5次。间隔 100ms
					02 持续按压状态 间隔 100ms，一直发送←
					03 抬起瞬间状态重复发送5次。间隔 100ms4
					00 持续抬起状态重复发送5次。间隔 100ms
			 */
			send(str1,str2,str3) {
				let str = '5A A5 05 82 0001 03 02';
				let arr = str.split(" ")
				arr[4] = _this.deviceCoding
				arr[5] = str1
				arr[6] = str2
				// let new_arr = arr.slice(3)
				// let str4 = getByteLength(new_arr.join(""))
				// arr[2] = str4
				let send_str = arr.join("")
				console.log('send_str: ',send_str,str3);
				for (var i = 0; i < _this.writes.length; i++) {
					let write = _this.writes[i]
					// 向蓝牙设备发送一个0x00的16进制数据
					const buffer = new ArrayBuffer(send_str.length * 2)
					const dataView = new Uint8Array(buffer)
					// dataView.setUint8(0, 0)
					for (var i = 0; i < send_str.length; i++) {
						dataView[i] = send_str.charCodeAt(i)
					}
					uni.writeBLECharacteristicValue({
						// 这里的 deviceId 需要在 getBluetoothDevices 或 onBluetoothDeviceFound 接口中获取
						deviceId: _this.deviceId,
						// 这里的 serviceId 需要在 getBLEDeviceServices 接口中获取
						serviceId: _this.services[0],
						// 这里的 characteristicId 需要在 getBLEDeviceCharacteristics 接口中获取
						characteristicId: write,
						// 这里的value是ArrayBuffer类型
						value: buffer,
						success(res) {
							console.log('writeBLECharacteristicValue success', res.errMsg)
						},
						fail(fail) {
							console.log('writeBLECharacteristicValue fail: ', fail);
						}
					})
				}
				console.log(_this.deviceId, _this.services, _this.writes);
				return
				let deviceId = '84:C2:E4:40:7E:E3'
				let serviceId = '9ECADC24-0EE5-A9E0-93F3-A3B50100406E'
				// let characteristicId = '00002A05-0000-1000-8000-00805F9B34FB'
				let characteristicId = '9ECADC24-0EE5-A9E0-93F3-A3B50200406E'
				console.log(_this.deviceId, _this.serviceId, _this.characteristicId);
				// 向蓝牙设备发送一个0x00的16进制数据
				const buffer = new ArrayBuffer(_this.content.length * 2)
				const dataView = new Uint8Array(buffer)
				// dataView.setUint8(0, 0)
				for (var i = 0; i < _this.content.length; i++) {
					dataView[i] = _this.content.charCodeAt(i)
				}
				uni.writeBLECharacteristicValue({
					// 这里的 deviceId 需要在 getBluetoothDevices 或 onBluetoothDeviceFound 接口中获取
					deviceId: deviceId,
					// 这里的 serviceId 需要在 getBLEDeviceServices 接口中获取
					serviceId: serviceId,
					// 这里的 characteristicId 需要在 getBLEDeviceCharacteristics 接口中获取
					characteristicId: characteristicId,
					// 这里的value是ArrayBuffer类型
					value: buffer,
					success(res) {
						console.log('writeBLECharacteristicValue success', res.errMsg)
					},
					fail(fail) {
						console.log('writeBLECharacteristicValue fail: ', fail);
					}
				})
			},
			//链接蓝牙
			connect(item) {
				uni.createBLEConnection({
					// 这里的 deviceId 需要已经通过 createBLEConnection 与对应设备建立链接
					deviceId: item.deviceId,
					success(res) {
						_this.$u.vuex('deviceName', item.name)
						_this.$u.vuex('deviceId', item.deviceId)
						_this.$u.vuex('isConnect', true)
						_this.parseDeviceCoding()
						_this.stopBluetoothDevicesDiscovery()
						_this.getBLEDeviceServices(item)
						console.log(res, "蓝牙连接成功")
					},
					fail(res) {
						console.log("蓝牙连接失败", res)
					}
				})
			},
			// 停止搜寻蓝牙设备
			stopBluetoothDevicesDiscovery() {
				uni.stopBluetoothDevicesDiscovery({
					success: e => {
						console.log('停止搜索蓝牙设备:' + e.errMsg);
					},
					fail: e => {
						console.log('停止搜索蓝牙设备失败，错误码：' + e.errCode);
					}
				});
			},
			//获取蓝牙的所有服务
			//这个地方使用了setTimeout等待一秒种再去获取，直接获取我们可能出现获取不到的情况
			getBLEDeviceServices(item) {
				setTimeout(() => {
					uni.getBLEDeviceServices({
						// 这里的 deviceId 需要已经通过 createBLEConnection 与对应设备建立链接
						deviceId: item.deviceId,
						success: (res) => {
							// console.log("成功",res)
							console.log('device services:', res)
							//这里会获取到好多个services  uuid  我们只存储我们需要用到的就行，这个uuid一般硬件厂家会给我们提供
							res.services.forEach((item1) => {
								_this.getBLEDeviceCharacteristics(item, item1.uuid)
								// if(item.uuid.indexOf("AE00")!=-1){
								//     this.serviceId = item.uuid;
								//     //进入特征
								//     this.getBLEDeviceCharacteristics()
								// }
								/**再多介绍一个采坑的记录
								那就是监听变化这个方法的使用
								最开始我是写在了_this.notifyBLECharacteristicValueChange()启用 notify 功能里面，可我发现只能监听一个，
								后来我就吧这个监听方法放在了获取蓝牙设备所有服务，这个地方可以监听到所有特征值的变化**/
								// 这里获取回调，读取成功的值就会在这个地方接收到！！！
								uni.onBLECharacteristicValueChange((res) => {
									console.log("监听成功", res)
									//res.value是ArrayBuffer类型的，官方给了一个方法转16进制，我们再进行操作
									let shiliu = ab2hex(res.value)
									console.log('shiliu', shiliu);
								})
							})
						}
					})
				}, 1000)
			},
			//获取蓝牙特征
			getBLEDeviceCharacteristics(item, serviceId) {
				setTimeout(() => {
					uni.getBLEDeviceCharacteristics({
						// 这里的 deviceId 需要已经通过 createBLEConnection 与对应设备建立链接
						deviceId: item.deviceId,
						// 这里的 serviceId 需要在 getBLEDeviceServices 接口中获取
						serviceId: serviceId,
						success: (res) => {
							console.log(res, '特征getBLEDeviceCharacteristics')
							// this.characteristics = res.characteristics
							// console.log(res.characteristics)
							//循环所有的uuid
							// for(let i=0;i<3;i++){
							//  this.notifyBLECharacteristicValueChange(res.characteristics[i].uuid)
							//  console.log(res.characteristics[i].uuid)
							//  console.log(i,'i')
							// }
							res.characteristics.forEach((item1) => {
								let {
									read,
									write,
									notify
								} = item1.properties
								if (notify) {
									_this.notifyBLECharacteristicValueChange(item, serviceId,item1.uuid)
								}
								if (write) {
									if (_this.serviceId == '') {
										_this.serviceId = item1.uuid
									}
									if (!_this.services.includes(serviceId)) {
										_this.services.push(serviceId)
									}
									if (!_this.writes.includes(item1.uuid)) {
										_this.writes.push(item1.uuid)
									}
									// _this.writeBLECharacteristicValue(item, serviceId, item1.uuid)
								}
								console.log('item1: ', item1);
								// _this.characteristicId = item1.uuid
								// _this.notifyBLECharacteristicValueChange(item,serviceId,item1.uuid)
								// if(item.uuid.indexOf("AE02") != -1){
								//     console.log('characteristicId:', item1.uuid)
								//     //利用传参的形势传给下面的notify，这里的uuid如果都需要用到，就不用做判断了，建议使用setTimeout进行间隔性的调用此方法
								//     this.notifyBLECharacteristicValueChange(item1.uuid)
								// }
							})
						},
						fail: (res) => {
							console.log(res)
						}
					})
				}, 1000)
			},
			async add_user_sb(){
				let params = {
					device_name:_this.deviceName,
					device_id:_this.deviceId,
					services:_this.serviceId,
					characteristics:_this.writes,
					write:1,
					notify:0,
				}
				const data = await _this.$post('port/add_user_sb',params)
				if (data.code == 200) {
					
				} else {
					uni.$u.toast(data.msg)
				}
			},
			// 启用 notify 功能
			notifyBLECharacteristicValueChange(item, serviceId, characteristicId) {
				uni.notifyBLECharacteristicValueChange({
					state: true, // 启用 notify 功能
					// 这里的 deviceId 需要已经通过 createBLEConnection 与对应设备建立链接
					deviceId: item.deviceId,
					// 这里的 serviceId 需要在 getBLEDeviceServices 接口中获取
					serviceId: serviceId,
					// 这里的 characteristicId 需要在 getBLEDeviceCharacteristics 接口中获取
					characteristicId: characteristicId,
					success: (res) => {
						// console.log(this.characteristicId)
						console.log(characteristicId, '--notifyBLECharacteristicValueChange success--', res)
					},
					fail: (res) => {
						console.log('notifyBLECharacteristicValueChange fail--', res.errMsg,
							`--${characteristicId}`)
					}
				})
			},
			//向低功耗蓝牙设备特征值中写入二进制数据。注意：必须设备的特征值支持 write 才可以成功调用。
			writeBLECharacteristicValue(item, serviceId, characteristicId) {
				let str = '666'
				// 向蓝牙设备发送一个0x00的16进制数据
				const buffer = new ArrayBuffer(str.length * 2)
				const dataView = new Uint8Array(buffer)
				// dataView.setUint8(0, 0)
				for (var i = 0; i < str.length; i++) {
					dataView[i] = str.charCodeAt(i)
				}
				uni.writeBLECharacteristicValue({
					// 这里的 deviceId 需要在 getBluetoothDevices 或 onBluetoothDeviceFound 接口中获取
					deviceId: item.deviceId,
					// 这里的 serviceId 需要在 getBLEDeviceServices 接口中获取
					serviceId: serviceId,
					// 这里的 characteristicId 需要在 getBLEDeviceCharacteristics 接口中获取
					characteristicId: characteristicId,
					// 这里的value是ArrayBuffer类型
					value: buffer,
					success(res) {
						console.log('writeBLECharacteristicValue success', res.errMsg, `--${characteristicId}`)
					},
					fail(fail) {
						console.log('writeBLECharacteristicValue fail: ', fail, `--${characteristicId}`);
					}
				})
			},
			getBluetoothAdapterState() {
				uni.getBluetoothAdapterState({
					success(res) {
						let adapterState = res.adapterState
						console.log(res, adapterState)
						// _this.openBluetoothSuccess = adapterState.available && adapterState.powered
						_this.openBluetoothSuccess = res.available
						if (_this.deviceId) {
							let item = {
								'deviceId':_this.deviceId,
								'name':_this.deviceName,
							}
							_this.connect(item)
							setTimeout(()=>{
								if (_this.load) {
									_this.load = false
								}
							},500)
						}else{
							if (_this.load) {
								_this.load = false
							}
						}
					},
					fail(fail) {
						_this.openBluetoothAdapter()
						console.log('fail: ', fail);
						if (_this.load) {
							_this.load = false
						}
					}
				})
			},
			openBluetoothAdapter() {
				uni.openBluetoothAdapter({
					success(res) {
						_this.openBluetoothSuccess = true
						console.log(res)
						if (_this.deviceId) {
							let item = {
								'deviceId':_this.deviceId,
								'name':_this.deviceName,
							}
							_this.connect(item)
						}
					},
					fail(fail) {
						console.log('fail: ', fail);
					}
				})
			},
			//开始搜寻附近的蓝牙外围设备。此操作比较耗费系统资源，请在搜索并连接到设备后调用 uni.stopBluetoothDevicesDiscovery 方法停止搜索。
			startBluetoothDevicesDiscovery() {
				// 以微信硬件平台的蓝牙智能灯为例，主服务的 UUID 是 FEE7。传入这个参数，只搜索主服务 UUID 为 FEE7 的设备
				uni.startBluetoothDevicesDiscovery({
					//要搜索的蓝牙设备主 service 的 uuid 列表。某些蓝牙设备会广播自己的主 service 的 uuid。
					//如果设置此参数，则只搜索广播包有对应 uuid 的主服务的蓝牙设备。建议主要通过该参数过滤掉周边不需要处理的其他蓝牙设备。
					//9ECADC24-0EE5-A9E0-93F3-A3B50100406E
					// services: ['FEE7'],
					success(res) {
						console.log(res)
					},
					fail(fail) {
						console.log('fail: ', fail);
					}
				})
				_this.isSearch = true
			},
			changeJt(index) {
				if (_this.jt_index == index) {
					return
				}
				let str = ''
				switch (index) {
					case 0:
						str = 'up'
						break;
					case 1:
						str = 'right'
						break;
					case 2:
						str = 'down'
						break;
					default:
						str = 'left'
						break;
				}
				_this.send(str)
				_this.jt_index = index
				setTimeout(() => {
					_this.jt_index = -1
				}, 500)
			}
		}
	}
